const NINTH_ORIGINAL_URL=new URL("../../../../../eighth-reconciliation/verify-dependencies.mjs",import.meta.url);
import {ninthLeaf,ninthHash,ninthEntry,ninthQuestion,ninthReferenceQuestion,ninthReferenceEntry,ninthIncludes,ninthFragment,ninthSubstantiveIncludes,ninthSourceText,ninthSourceHash,ninthRegistryBefore,ninthEntryHash,ninthKeyIncludes,ninthKeyHash,ninthKeyFragment,ninthKeyQuestion} from '../../../../verify-reference.mjs';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
const root=new URL('../../../',NINTH_ORIGINAL_URL),read=p=>JSON.parse(fs.readFileSync(new URL(p,NINTH_ORIGINAL_URL),'utf8'));
export const sha=s=>createHash('sha256').update(s).digest('hex');
const raw=fs.readFileSync(new URL('./transition-proof.json',NINTH_ORIGINAL_URL));
assert.equal(sha(raw),'57e5b4d787636574823ca61a1d2c7f893900fdbf81ed3cb835aff0ce48a3b04c','eighth immutable whole-object transition proof');
export const eighthProof=JSON.parse(raw);const R=eighthProof.records;
assert.equal(R.length,145);assert.equal(new Set(R.map(r=>JSON.stringify([r.entryId,r.path]))).size,145);
const get=(o,p)=>p.reduce((x,k)=>x?.[k],o),set=(o,p,v)=>{p.slice(0,-1).reduce((x,k)=>x[k],o)[p.at(-1)]=v;};
const samePath=(a,b)=>JSON.stringify(a)===JSON.stringify(b),record=(id,p)=>R.find(r=>r.entryId===id&&samePath(r.path,p));
for(const r of R){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.notEqual(r.before,r.after);assert.equal(get(eighthProof.originalEntries[r.entryId],r.path),r.before);assert.equal(get(eighthProof.finalEntries[r.entryId],r.path),r.after);}
for(const [id,old]of Object.entries(eighthProof.originalEntries)){const expected=structuredClone(old);for(const r of R.filter(r=>r.entryId===id)){assert.equal(get(expected,r.path),r.before);set(expected,r.path,r.after);}assert.deepEqual(expected,eighthProof.finalEntries[id],'only exact approved full-object transitions');}
export function eighthLeaf(id,p,old){const r=record(id,p);return ninthLeaf(id,p,r&&old===r.before?r.after:old);}
export function eighthHash(id,p,old){const r=record(id,p);return ninthHash(id,p,r&&old===r.beforeSha256?r.afterSha256:old);}
export function eighthEntry(old){const next=structuredClone(old);for(const r of R.filter(r=>r.entryId===old.id)){if(get(next,r.path)===r.before)set(next,r.path,r.after);}return ninthEntry(next);}
export function eighthQuestion(id,index,old){const next=structuredClone(old);for(const r of R.filter(r=>r.entryId===id&&r.path[0]==='items'&&r.path[1]===index)){const p=r.path.slice(2);if(get(next,p)===r.before)set(next,p,r.after);}return ninthQuestion(id,index,next);}
// A historical reference is reconstructed only after the entire actual current question is exact.
export function eighthReferenceQuestion(id,index,current){current=ninthReferenceQuestion(id,index,current);const rs=R.filter(r=>r.entryId===id&&r.path[0]==='items'&&r.path[1]===index);if(!rs.length)return current;assert.deepEqual(current,eighthProof.finalEntries[id].items[index],'exact final question required before historical reference');const old=structuredClone(current);for(const r of rs){assert.equal(get(old,r.path.slice(2)),r.after);set(old,r.path.slice(2),r.before);}assert.deepEqual(old,eighthProof.originalEntries[id].items[index]);return old;}
export function assertEighthAll(E){for(const [id,expected]of Object.entries(eighthProof.finalEntries))assert.deepEqual(E.get(id),ninthEntry(expected),'all fields of reviewed full entry '+id);return {leaves:R.length,entries:Object.keys(eighthProof.finalEntries).length};}
const units=read('./small-witness-migrations.json').rows;
for(const u of units){assert.equal(sha(u.before),u.beforeSha256);assert.equal(sha(u.after),u.afterSha256);let x=u.before;for(const e of u.paragraphEdits){assert.equal(sha(e.before),e.beforeSha256);assert.equal(sha(e.after),e.afterSha256);assert.equal(x.split(e.before).length,2);x=x.replace(e.before,e.after);}assert.equal(x,u.after);const r=record(u.entryId,u.path);assert.ok(r.before.includes(u.before)&&r.after.includes(u.after));}
export function eighthIncludes(id,p,actual,oldHtml){assert.equal(typeof actual,'string');if(ninthIncludes(id,p,actual,oldHtml))return true;const r=record(id,p);if(!r)return false;assert.equal(actual,ninthLeaf(id,p,r.after),'exact final body before migrated witness');const found=units.filter(u=>u.entryId===id&&samePath(u.path,p)&&u.before===oldHtml);if(!found.length)return false;assert.ok(r.before.includes(oldHtml),'old complete body must contain original witness');for(const u of found)assert.ok(ninthIncludes(id,p,actual,u.after),'entire migrated substantive section required');return true;}
let sourceProof;
const sources=()=>sourceProof??=read('./source-transition-proof.json');
export function eighthSourceText(relative,old){const r=sources().transitions.find(r=>r.target===relative&&r.before===old);return ninthSourceText(relative,r?r.after:old);}
export function eighthSourceHash(relative,old){const r=sources().transitions.find(r=>r.target===relative&&r.beforeSha256===old);return ninthSourceHash(relative,r?r.afterSha256:old);}
export function assertEighthSourceTransitions(){const p=sources();for(const r of p.transitions){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);let out='',pos=0;for(const e of r.edits){assert.ok(e.beforeStart>=pos);assert.equal(r.before.slice(e.beforeStart,e.beforeEnd),e.before);out+=r.before.slice(pos,e.beforeStart)+e.after;pos=e.beforeEnd;}out+=r.before.slice(pos);assert.equal(out,r.after,'complete exact code reconstruction');assert.equal(fs.readFileSync(new URL(r.target,root),'utf8'),ninthSourceText(r.target,r.after),'only reviewed code edits '+r.target);}for(const [p,h]of Object.entries(sources().originalDataFiles))assert.equal(sha(fs.readFileSync(new URL(p,root))),h,'original fixture data changed '+p);return p.transitions.length;}
let reasonProof;const reasoning=()=>reasonProof??=JSON.parse(fs.readFileSync(new URL('../reasoning-variant-cleanup/precise-add-proof.json',NINTH_ORIGINAL_URL),'utf8'));
const verified=new WeakSet();
export function assertReasoningMigrations(E){if(verified.has(E))return;const p=reasoning();assert.equal(p.variantMigrations.length,347);let conditions=0,archive=0;for(const f of p.oldFixtureReferences){const bytes=fs.readFileSync(new URL(f.fixture,root));assert.equal(sha(bytes),f.fixtureSha256);const data=JSON.parse(bytes);for(const a of f.assertions){assert.equal(get(data,a.jsonPath),a.sourceHtml);assert.equal(sha(a.sourceHtml),a.sourceSha256);}}
 for(const m of p.variantMigrations){assert.equal(sha(m.sourceHtml),m.sourceSha256);const r=record(m.sourceEntryId,m.sourcePath);assert.ok(r.before.includes(m.sourceHtml));assert.equal(get(E.get(r.entryId),r.path),ninthLeaf(r.entryId,r.path,r.after),'actual source after before semantic migration');if(m.status==='AMBIGUOUS_ARCHIVE_ONLY'){archive++;assert.equal(m.sourceVariantIndex,117);assert.equal(m.sourceHtml,'<li>- React的原理</li>');assert.equal(m.destinations.length,0);assert.equal(m.conditions.length,0);assert.ok(m.archive);continue;}assert.equal(m.status,'REVIEWED_SUBSTANTIVE_EVIDENCE');assert.ok(m.conditions.length);for(const c of m.conditions){conditions++;assert.ok(c.witnessIds.length);for(const id of c.witnessIds)assert.ok(m.destinations.some(d=>d.kind==='substantive-answer'&&d.witnessId===id));}assert.equal(m.destinations.filter(d=>d.kind==='normalized-question').length,1);for(const d of m.destinations){assert.equal(sha(d.html),d.sha256);const actual=get(E.get(d.entryId),d.path);assert.equal(typeof actual,'string');if(d.kind==='substantive-answer'){assert.match(d.html,/^<(p|li)\b/);assert.ok(d.html.replace(/<[^>]*>/g,'').length>15);assert.ok(ninthSubstantiveIncludes(d.entryId,d.path,actual,d.html),'independent original condition lost '+d.witnessId);}else{assert.equal(d.kind,'normalized-question');assert.ok(actual.includes(d.html),'relocated normalized question missing');}}}
 assert.equal(conditions,556);assert.equal(archive,1);verified.add(E);
}
export function eighthReasoningIncludes(E,id,index,oldHtml){const actual=E.get(id)?.items?.[index]?.a;assert.equal(typeof actual,'string');if(actual.includes(oldHtml))return true;const r=record(id,['items',index,'a']);assert.ok(r,'unapproved missing original destination');assert.equal(actual,ninthLeaf(id,['items',index,'a'],r.after));assert.ok(r.before.includes(oldHtml));const refs=reasoning().oldFixtureReferences.flatMap(f=>f.assertions).filter(a=>a.sourceEntryId===id&&samePath(a.sourcePath,r.path)&&a.sourceHtml===oldHtml);assert.ok(refs.length,'missing oracle reference must have exact classified provenance');assertReasoningMigrations(E);for(const ref of refs){assert.ok(ref.sourceVariantIndices.length);for(const i of ref.sourceVariantIndices)assert.ok(reasoning().variantMigrations.some(m=>m.sourceEntryId===id&&samePath(m.sourcePath,r.path)&&m.sourceVariantIndex===i));}return true;}
